        }
        return res;
    }
};

class Solution {
    public List<String> findStrobogrammatic(int n) {
        return helper(n, n);
    }

    private List<String> helper(int m, int total) {
        if (m == 0) return Collections.singletonList("");
        if (m == 1) return Arrays.asList("0", "1", "8");
        List<String> prev = helper(m - 2, total);
        List<String> res = new ArrayList<>();
        for (String p : prev) {
            if (m != total) res.add("0" + p + "0");
            res.add("1" + p + "1");
            res.add("6" + p + "9");
            res.add("8" + p + "8");
            res.add("9" + p + "6");
        }
        return res;
    }
}

