var findStrobogrammatic = function(n) {
    function helper(m, total) {
        if (m === 0) return [""];
        if (m === 1) return ["0", "1", "8"];
        const prev = helper(m - 2, total);
        const res = [];
        for (const p of prev) {
            if (m !== total) res.push("0" + p + "0");
            res.push("1" + p + "1");
            res.push("6" + p + "9");
            res.push("8" + p + "8");
            res.push("9" + p + "6");
        }
        return res;
    }
    return helper(n, n);
};
